// Capture of the guided dictation in the assistant panel, opened from a patient
// file without a visit (field test of 2026-10-25): the four rubrics are typed
// (fictional "Max" case), the note is generated by the real model, then each
// state is photographed by the shell (signal file "ready:<name>" → "done:<name>").
import { readTextFile, writeTextFile } from "@tauri-apps/plugin-fs";

export const sleep = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));
export const waitFor = async <T>(probe: () => T | null | undefined | false, timeout = 30_000) => {
  const started = Date.now();
  for (;;) {
    const value = probe();
    if (value) return value;
    if (Date.now() - started > timeout) throw new Error("Élément introuvable pour la capture.");
    await sleep(250);
  }
};
const buttons = () => [...document.querySelectorAll<HTMLButtonElement>("button")];
export const button = (text: string) => buttons().find((element) => element.textContent?.includes(text) && !element.disabled);
export const setTextarea = (area: HTMLTextAreaElement, value: string) => {
  Object.getOwnPropertyDescriptor(HTMLTextAreaElement.prototype, "value")!.set!.call(area, value);
  area.dispatchEvent(new Event("input", { bubbles: true }));
};

const setInput = (input: HTMLInputElement, value: string) => {
  Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, "value")!.set!.call(input, value);
  input.dispatchEvent(new Event("input", { bubbles: true }));
};

// The capture runs on an empty, temporary data folder: a test account with a
// generated password (never shown, discarded with the folder) opens the session.
export async function ensureSession() {
  await waitFor(() => document.querySelector("#email") || document.querySelector("[data-sidebar]"));
  if (!document.querySelector("#email")) return;
  button("Créer un compte")?.click();
  const name = await waitFor(() => document.querySelector<HTMLInputElement>("#name"));
  const secret = [...crypto.getRandomValues(new Uint8Array(12))].map((byte) => byte.toString(16).padStart(2, "0")).join("");
  setInput(name, "Dr Capture Test");
  setInput(document.querySelector<HTMLInputElement>("#email")!, "capture@exemple.test");
  setInput(document.querySelector<HTMLInputElement>("#password")!, secret);
  await sleep(300);
  document.querySelector<HTMLButtonElement>('button[type="submit"]')!.click();
  await waitFor(() => document.querySelector("[data-sidebar]"), 60_000);
}

/** The fictional patient of the reference case, created once in the temporary database. */
export async function ensurePatient() {
  const { generateId, runDbOperation, runDbRead } = await import("@/services/sqlite/database");
  const found = await runDbRead((db) => db.select<{ id: string }[]>("SELECT id FROM patients WHERE name = 'Max'"));
  if (found[0]) return found[0].id;
  const ownerId = generateId();
  const patientId = generateId();
  await runDbOperation((db) =>
    db.execute("INSERT INTO owners (id, first_name, last_name, phone) VALUES (?, 'Propriétaire', 'Fictif', '0000000000')", [ownerId]),
  );
  await runDbOperation((db) =>
    db.execute("INSERT INTO patients (id, owner_id, name, species, breed, sex, status) VALUES (?, ?, 'Max', 'Chien', 'Berger Allemand', 'M', 'sante')", [patientId, ownerId]),
  );
  // The app's stores were read before the insert: reload, the scenario resumes from here.
  location.reload();
  return null;
}

export async function captureDictation(signal: string, casePath: string) {
  const shot = async (name: string) => {
    await sleep(800);
    await writeTextFile(signal, `ready:${name}`);
    for (let i = 0; i < 600 && (await readTextFile(signal).catch(() => "")).trim() !== `done:${name}`; i++) await sleep(500);
  };
  const rubrics = (JSON.parse(await readTextFile(casePath)) as { rubriques: Record<string, string> }).rubriques;
  await ensureSession();
  const patientId = await ensurePatient();
  if (!patientId) return;
  location.hash = `#/patient/${encodeURIComponent(patientId)}`;
  await waitFor(() => document.body.innerText.includes("Dossier patient"));
  await sleep(1500);
  const open = await waitFor(() =>
    buttons().find((element) => /assistant/i.test(element.getAttribute("aria-label") ?? element.textContent ?? "")),
  );
  open.click();
  for (const [index, key] of ["subjective", "objective", "assessment", "plan"].entries()) {
    const area = await waitFor(() => document.querySelector<HTMLTextAreaElement>("textarea.assistant-dictation-field"));
    setTextarea(area, rubrics[key]);
    await sleep(400);
    if (index < 3) (await waitFor(() => button("Continuer vers")))?.click();
  }
  await shot("rubrique-plan");
  (await waitFor(() => button("Relire la note SOAP")))?.click();
  // Real generation: the review tab opens, or the refusal is shown.
  await sleep(2000);
  await waitFor(() => document.querySelector('[role="alert"]') || document.body.innerText.includes("Relecture & Validation SOAP"), 600_000);
  const refused = Boolean(document.querySelector('[role="alert"]'));
  await writeTextFile(`${signal}.issue`, refused ? `refus: ${document.querySelector('[role="alert"]')?.textContent}` : "acceptée");
  if (refused) {
    document.querySelector('[role="alert"]')!.scrollIntoView({ block: "center" });
    await shot("refus");
    const escape = button("Relire ma dictée comme note");
    if (escape) {
      escape.click();
      await waitFor(() => document.body.innerText.includes("Relecture & Validation SOAP"));
      await shot("note-depuis-dictee");
    }
  } else {
    await shot("note-generee");
    document.getElementById("soap-field-plan")?.scrollIntoView({ block: "center" });
    await shot("note-generee-plan");
  }
  await writeTextFile(signal, "restored");
}
